/** Returns Extensivo teoria lessons (non-exercise) for a subject, in order */
export function getTeoriaLessons(subjectId: string): PlatformLesson[] {
  return (PLATFORM_LESSONS[subjectId]?.extensivo ?? []).filter(l => !l.isExercise);
}

/** Returns Extensivo exercise-list lessons for a subject, in order */
export function getExercicioLessons(subjectId: string): PlatformLesson[] {
  return (PLATFORM_LESSONS[subjectId]?.extensivo ?? []).filter(l => l.isExercise);
}

/** Returns Zonas de Aprendizado lessons for a subject */
export function getZonasLessons(subjectId: string): PlatformLesson[] {
  return PLATFORM_LESSONS[subjectId]?.zonas ?? [];
}